from __future__ import annotations

import json
import os
import unicodedata
from pathlib import Path
from typing import Optional, Tuple, Union

from . import format, store

AppendTuple = Tuple


class ConflictError(Exception):
    pass


class _Tail:
    __slots__ = ("prev_hash",)

    def __init__(self, prev_hash: str) -> None:
        self.prev_hash = prev_hash


class Ledger:
    def __init__(self, path: Union[str, os.PathLike]) -> None:
        self.path = Path(path)

    def _read_tail_prev_hash(self) -> str:
        if not self.path.exists():
            return format.GENESIS
        raw = self.path.read_bytes()
        if raw == b"":
            return format.GENESIS
        last_nl = raw.rfind(b"\n")
        if last_nl == -1:
            return format.GENESIS
        last_line = raw[last_nl + 1:]
        try:
            obj = json.loads(last_line)
        except json.JSONDecodeError:
            return format.GENESIS
        return obj.get("hash", format.GENESIS)

    def _build_line(self, op_tuple: Tuple) -> dict:
        op = op_tuple[0]
        if op == "put":
            _, key, value, rid, ts = op_tuple
        elif op == "delete":
            _, key, rid, ts = op_tuple
            value = None
        else:
            raise ValueError(f"unknown op: {op!r}")

        nfc_key = unicodedata.normalize("NFC", key)
        if nfc_key == "":
            raise ValueError("key must not be empty after NFC normalization")

        line: dict = {
            "op": op,
            "key": nfc_key,
            "ts": ts,
            "id": rid,
        }
        if op == "put":
            line["value"] = value

        prev_hash = self._read_tail_prev_hash()
        line["hash"] = ""
        line["prev_hash"] = prev_hash
        line["hash"] = format.line_hash(prev_hash, line)
        return line

    def append(self, op_tuple: Tuple) -> dict:
        line = self._build_line(op_tuple)
        body = format.canonical_bytes(line) + b"\n"
        existed = self.path.exists() and self.path.stat().st_size > 0
        if existed:
            with open(self.path, "ab") as f:
                f.write(body)
                f.flush()
                os.fsync(f.fileno())
        else:
            store.write_atomic(self.path, [body])
        return line

